const calculateGniGroupBySectorChartData = (
  databases,
  indicatorId,
  sectorIds,
  methodIds,
  seriesNames
) => {
  const database = databases.reportingYear;

  const methodSet =
    methodIds ||
    new Set(Object.keys(database.methods).map(id => parseInt(id, 10)));

  let data = addSectorTotals(database.data).filter(
    datum =>
      datum.indicator === indicatorId &&
      sectorIds.has(datum.sector) &&
      methodSet.has(datum.method) &&
      (!datum.year || datum.year === reportingYear)
  );

  const areaIds = new Set([14, 15, 23]);

  console.log(data);

  data = data
    .filter(datum => areaIds.has(datum.area))
    .map(datum => {
      const area = getGniGroupCode(database.areas[datum.area].area);

      let sector = database.sectors[datum.sector];

      sector =
        {
          "Private Sub": "Private Subsidized",
          "Private Non-Sub": "Private Non-Subsidized"
        }[sector] || sector;

      return {
        ...datum,
        area,
        sector
      };
    });

  console.log(data);

  const totalSpend = summarize(data, [])[0].value;

  const areaMix = summarize(data, ["area"])
    .map(datum => ({
      ...datum,
      sector: "Total",
      value: datum.value / totalSpend
    }))
    .reduce((result, datum) => {
      result[datum.area] = datum.value;

      return result;
    }, {});

  const areaTotals = summarize(data, ["area"]).map(datum => ({
    ...datum,
    sector: "Total"
  }));

  const summary = summarize(data, ["area", "sector"]);

  const sectorMix = calculateMix(
    [...summary, ...areaTotals],
    "sector",
    "area",
    "Total"
  ).filter(datum => datum.sector !== "Total");

  return seriesNames.map(seriesName => ({
    name: seriesName.replace("Private ", ""),
    color: styleConstants.categoryColors.sectorColors[seriesName],
    data: orderByValues(
      sectorMix.filter(datum => datum.sector === seriesName),
      ["LIC", "L-MIC", "U-MIC"],
      "area"
    ).map(datum => [datum.area, datum.value * 100, areaMix[datum.area] * 100])
  }));
};

const calculateMethodMixChartData = (databases, indicatorId, sectorId) => {
  const database = databases.reportingYear;

  const areaIds = new Set([14, 15, 23]);

  const sectorIds = new Set(sectorId ? [sectorId] : [3, 6]);

  const data = addSectorTotals(database.data)
    .filter(
      datum =>
        areaIds.has(datum.area) &&
        datum.indicator === indicatorId &&
        sectorIds.has(datum.sector) &&
        datum.year === reportingYear
    )
    .map(datum => ({
      ...datum,
      area: database.areas[datum.area].area,
      method: database.methods[datum.method]
    }));

  return summarize(data, ["area", "method"]);
};

// Table 1.1
export const calculateTheme1CurrentSpendingBySectorTableData = databases => {
  const database = databases.reportingYear;

  const areaIds = new Set([14, 15, 23]);

  const data = database.data
    .filter(datum => datum.indicator === 2 && areaIds.has(datum.area))
    .map(datum => ({
      ...datum,
      area: database.areas[datum.area].area
    }));

  const summary = summarize(addSectorTotals(data), ["area", "sector"]).map(
    datum => ({
      ...datum,
      sector: database.sectors[datum.sector]
    })
  );

  const areaTotals = summarize(data, ["area"]).map(total => ({
    ...total,
    sector: "Total"
  }));

  const sectorTotals = summarize([...areaTotals, ...summary], ["sector"]).map(
    total => ({
      ...total,
      area: "Total"
    })
  );

  return [...summary, ...areaTotals, ...sectorTotals];
};

