// Figures 5.1 and 5.5
export const calculateTheme5ChangeByMethodChartData = (
  databases,
  areaId,
  indicatorId
) => {
  const database = databases.core;

  return getChangeData(
    database.data.filter(
      datum => datum.area === areaId && datum.indicator === indicatorId
    ),
    "method"
  )
    .map(datum => ({
      ...datum,
      method:
        datum.method !== "Total" ? database.methods[datum.method] : "Total"
    }))
    .filter(datum => datum.method !== "Total");
};

// Figure 5.2
export const calculateTheme5ChangeInMethodMixChartData = (
  databases,
  areaId
) => {
  const database = databases.core;

  const data = database.data
    .filter(datum => datum.area === areaId && datum.indicator === 4)
    .map(datum => ({
      ...datum,
      method: database.methods[datum.method]
    }));

  const summary = summarize(data, ["method", "year"]);

  const yearTotals = summarize(data, ["year"]).map(datum => ({
    ...datum,
    method: "Total"
  }));

  const methodMix = calculateMix(
    [...summary, ...yearTotals],
    "method",
    "year",
    "Total"
  );

  const users = summary.reduce((result, datum) => {
    result[`${datum.method} ${datum.year}`] = datum.value;

    return result;
  }, {});

  return getChangeData(methodMix, "method")
    .map(datum => ({
      ...datum,
      users: users[`${datum.method} ${datum.year}`]
    }))
    .filter(datum => !isNaN(datum.year));
};

